work <- path.expand('~/.cache/comptoxr-specmill-finish/protocol-get-candidate')
out <- file.path(work, 'evidence')
loadNamespace('specmill', lib.loc = normalizePath('dev/specmill-pilot/artifacts/toolkit-library/0.1.45'))
stopifnot(as.character(packageVersion('specmill')) == '0.1.45', packageDescription('specmill')[['Config/specmill/source-commit']] == 'f686717052b7636775ce1ccca2080056c32f69f0')
stopifnot(all(file.copy(c('R/api_validation.R', 'R/service_endpoints.R', 'R/api_auth.R', 'R/stdizer_protocol_policy.R'), file.path(work,'R'), overwrite=TRUE)))
settings <- jsonlite::read_json('.specmill/helpers/.ct_request.json')$settings
settings$companions <- unlist(settings$companions)
scaffold <- do.call(getFromNamespace('request_helper_scaffold','specmill'), settings)
writeLines(scaffold$code, file.path(work,'R/z_specmill_request.R'))
dir.create(file.path(work,'.specmill/helpers'),recursive=TRUE,showWarnings=FALSE)
writeLines(scaffold$provenance,file.path(work,'.specmill/helpers/.ct_request.json'))
writeLines(c('Package: ComptoxR','Title: Protocol GET candidate','Version: 3.0.0','Authors@R: person("Sean", "Thimons", email="seanthimons@outlook.com", role=c("aut", "cre"))','Description: Isolated reviewed GET source candidate.','License: MIT','Encoding: UTF-8','Imports: httr2, jsonlite, cli, curl, lifecycle'),file.path(work,'DESCRIPTION'))
yaml::write_yaml(list(config_version=1L,package='ComptoxR',formatter=list(name='air',version='0.11.0'),services=list('apis/service.yml')),file.path(work,'specmill.yml'))
args <- list(root=work,config='specmill.yml',validation=TRUE,artifacts=c('wrappers','documentation'))
applied <- do.call(specmill::generate_client,c(args,list(mode='apply')))
fresh <- do.call(specmill::generate_client,c(args,list(mode='check')))
saveRDS(list(applied=applied,fresh=fresh),file.path(out,'generation.rds'))
stopifnot(length(fresh$operations)==1L,!length(fresh$diagnostics),!length(fresh$mapping_diagnostics),!length(fresh$retained_diagnostics),!length(fresh$drift),all(vapply(fresh$validation,function(x) identical(x$status,'passed'),TRUE)),all(vapply(fresh$files,function(x) identical(x$action,'unchanged'),TRUE)))
manifest <- jsonlite::read_json(file.path(work,'.specmill/manifest.json'))$files
for(file in names(manifest)) stopifnot(identical(specmill:::output_hash(file.path(work,file)),manifest[[file]]$hash))
jsonlite::write_json(list(version='0.1.45',source_commit=packageDescription('specmill')[['Config/specmill/source-commit']],validation=fresh$validation,operations=1L,owners=length(manifest),freshness=TRUE),file.path(out,'generation.json'),auto_unbox=TRUE,pretty=TRUE)
cat('PASS: validated official45 GET generation/freshness.\n')
